package io.github.diodeme.ji.ai;

import java.util.Map;
import java.util.Set;

/** Configured model candidate. Runtime capability negotiation remains authoritative. */
public record ProviderModel(String id, String displayName, Set<Capability> capabilities, Map<String, Object> settings) {
    public ProviderModel {
        if (id == null || id.isBlank()) throw new IllegalArgumentException("model id must not be blank");
        if (displayName == null || displayName.isBlank()) throw new IllegalArgumentException("displayName must not be blank");
        capabilities = Set.copyOf(capabilities);
        settings = Map.copyOf(settings);
    }

    public enum Capability { TEXT, STREAMING, TOOL_CALL, USAGE, REASONING, IMAGE_INPUT }
}
